contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address to, uint256 v) public {
        require(to != address(0), "recipient must be nonzero");
        uint256 supply0 = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 bal0 = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 toBal0 = c.balanceOf(to); if (__ESBMC_reverted()) return;
        require(v <= bal0, "value must not exceed balance");

        c.freezeAccount(address(this), true); if (__ESBMC_reverted()) return;

        bool reverted;
        c.transfer(to, v); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(
            reverted &&
            c.balanceOf(address(this)) == bal0 &&
            c.balanceOf(to) == toBal0 &&
            c.totalSupply() == supply0
        );
    }
    receive() external payable {}
}

